"""Vietnamese member pages served by the Canvas host."""
PAGE = '''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Thành viên · Canvas Muse</title>
<style>body{margin:0;background:#0c1019;color:#e9edf7;font:16px system-ui}*{box-sizing:border-box}header{padding:18px 5%;border-bottom:1px solid #30384b;display:flex;gap:20px;flex-wrap:wrap;align-items:center}a{color:#9fc4ff;text-decoration:none}main{max-width:1000px;margin:40px auto;padding:0 20px}form,.card{padding:24px;border:1px solid #30384b;border-radius:16px;background:#151c2b;margin:18px 0}label{display:block;margin:14px 0 6px}input,textarea,select{width:100%;padding:12px;border:1px solid #46526b;border-radius:8px;color:inherit;background:#0e1522;font:inherit}textarea{min-height:160px}button{cursor:pointer;background:#3874e6;color:white;border:0;padding:11px 18px;border-radius:8px;font:inherit;margin:8px 8px 0 0}button:disabled{opacity:.5;cursor:wait}.secondary{background:#303c54}.danger{background:#9c3547}#notice{white-space:pre-wrap;color:#ffcb8e;min-height:24px}p{line-height:1.6}.muted{color:#a6b2c9}.auth{max-width:480px;margin:auto}.row{display:flex;gap:15px;align-items:center;flex-wrap:wrap}.row>*{flex:1}.content{white-space:pre-wrap;overflow-wrap:anywhere}.hidden{display:none}small{color:#a6b2c9}h1{font-size:28px}h2{font-size:20px}</style></head><body><header><a href="/">Canvas Muse</a><a href="/image">Tạo ảnh</a><a href="/video">Tạo video</a><a href="/prompts">Thư viện lời nhắc</a><a id="adminLink" class="hidden" href="/members">Quản lý thành viên</a><span id="account"></span><button id="logout" class="secondary hidden">Đăng xuất</button></header><main><div id="notice" role="status" aria-live="polite"></div><div id="app"></div></main>
<script>
let me=null, prompts=[], editing=null;const app=document.getElementById('app'),notice=document.getElementById('notice');
function message(text){notice.textContent=text;}
async function api(path,data){const options={credentials:'same-origin',headers:{}};if(data!==undefined){options.method='POST';options.headers={'Content-Type':'application/json','X-CSRF-Token':me?.csrf||''};options.body=JSON.stringify(data);}const r=await fetch('/member-api/'+path,options);const out=await r.json();if(!r.ok)throw Error(out.error||'Yêu cầu thất bại.');return out;}
function node(tag,text,cls){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el;}
function action(parent,text,fn,cls){const b=node('button',text,cls);b.type='button';b.onclick=async()=>{b.disabled=true;message('');try{await fn();}catch(e){message(e.message);}finally{b.disabled=false;}};parent.append(b);return b;}
function field(form,label,name,type='text'){const id='field-'+name;const lab=node('label',label);lab.htmlFor=id;form.append(lab);const input=document.createElement(type==='textarea'?'textarea':'input');input.id=id;input.name=name;if(type!=='textarea')input.type=type;input.required=true;if(type==='password'){input.minLength=8;input.maxLength=128;input.autocomplete=location.pathname==='/register'?'new-password':'current-password';}if(name==='phone'){input.autocomplete='tel';input.inputMode='tel';input.placeholder='09xxxxxxxx';}form.append(input);return input;}
function authPage(register){app.className='auth';app.append(node('h1',register?'Đăng ký thành viên':'Đăng nhập'));app.append(node('p',register?'Tài khoản mới cần được admin duyệt trước khi sử dụng.':'Dùng số điện thoại và mật khẩu của bạn.','muted'));const form=document.createElement('form');field(form,'Số điện thoại','phone','tel');field(form,'Mật khẩu','password','password');if(register)field(form,'Nhập lại mật khẩu','password_confirm','password');const submit=node('button',register?'Đăng ký':'Đăng nhập');submit.type='submit';form.append(submit);form.onsubmit=async e=>{e.preventDefault();submit.disabled=true;message('');try{const data=Object.fromEntries(new FormData(form));const out=await api(register?'register':'login',data);if(register){form.reset();message(out.message);}else location.href='/';}catch(err){message(err.message);}finally{submit.disabled=false;}};app.append(form);const a=node('a',register?'Đã có tài khoản? Đăng nhập':'Chưa có tài khoản? Đăng ký');a.href=register?'/login':'/register';app.append(a);}
async function membersPage(){app.replaceChildren(node('h1','Quản lý thành viên'));const data=await api('members');app.append(node('p','Thành viên mới phải được duyệt để đăng nhập. Khóa tài khoản sẽ kết thúc phiên đăng nhập hiện có.','muted'));const labels={pending:'Chờ duyệt',approved:'Đã duyệt',blocked:'Đã khóa'};for(const u of data.members){const card=node('section',undefined,'card');card.append(node('h2',u.phone),node('p',(u.role==='admin'?'Admin · ':'Thành viên · ')+labels[u.status]));if(u.role!=='admin'){for(const [status,label] of [['approved','Duyệt / Mở khóa'],['blocked','Khóa / Từ chối']]){if(status!==u.status)action(card,label,async()=>{await api('members',{id:u.id,status});await membersPage();},status==='blocked'?'danger':'');}}app.append(card);}}
function editor(){const wrap=document.getElementById('editor');wrap.replaceChildren();const form=document.createElement('form');form.append(node('h2',editing?'Sửa lời nhắc':'Thêm lời nhắc'));const title=field(form,'Tiêu đề','title'),content=field(form,'Nội dung lời nhắc','content','textarea');title.maxLength=200;content.maxLength=50000;const select=document.createElement('select');select.name='scope';select.id='prompt-scope';const label=node('label','Phạm vi hiển thị');label.htmlFor=select.id;form.append(label);for(const [val,text] of me.role==='admin'?[['shared','Thư viện chung — mọi thành viên đều thấy'],['private','Riêng tư — chỉ chủ sở hữu và admin']]:[['private','Thư viện riêng của tôi']]){const option=node('option',text);option.value=val;select.append(option);}form.append(select);if(editing){title.value=editing.title;content.value=editing.content;select.value=editing.scope;}const save=node('button','Lưu lời nhắc');save.type='submit';form.append(save);action(form,'Hủy / Tạo mới',()=>{editing=null;editor();},'secondary');form.onsubmit=async e=>{e.preventDefault();save.disabled=true;message('');try{await api('prompts',{id:editing?.id,title:title.value,content:content.value,scope:select.value});editing=null;await libraryPage();message('Đã lưu lời nhắc.');}catch(err){message(err.message);}finally{save.disabled=false;}};wrap.append(form);}
async function libraryPage(){prompts=(await api('prompts')).prompts;app.replaceChildren(node('h1','Thư viện lời nhắc'));app.append(node('p',me.role==='admin'?'Bạn quản lý thư viện chung và toàn bộ lời nhắc của thành viên.':'Bạn xem được thư viện chung và lời nhắc riêng của mình. Admin có quyền quản lý lời nhắc riêng.','muted'));const edit=node('div');edit.id='editor';app.append(edit);editor();const search=node('input');search.placeholder='Tìm lời nhắc…';search.setAttribute('aria-label','Tìm lời nhắc');app.append(search);const list=node('div');app.append(list);const draw=()=>{list.replaceChildren();for(const p of prompts.filter(p=>(p.title+' '+p.content).toLocaleLowerCase().includes(search.value.toLocaleLowerCase()))){const card=node('section',undefined,'card');card.append(node('h2',p.title),node('small',p.scope==='shared'?'Thư viện chung':(me.role==='admin'&&p.owner_phone?'Riêng tư · '+p.owner_phone:'Riêng tư')),node('p',p.content,'content'));action(card,'Sao chép',async()=>{await navigator.clipboard.writeText(p.content);message('Đã sao chép lời nhắc.');});if(me.role==='admin'||p.owner===me.id){action(card,'Sửa',()=>{editing=p;editor();document.getElementById('editor').scrollIntoView({behavior:'smooth'});},'secondary');action(card,'Xóa',async()=>{if(!confirm('Xóa lời nhắc này?'))return;await api('prompts',{id:p.id,action:'delete'});await libraryPage();},'danger');}list.append(card);}if(!list.childElementCount)list.append(node('p','Chưa có lời nhắc.','muted'));};search.oninput=draw;draw();}
(async()=>{try{me=(await api('me')).user;if(me){document.getElementById('account').textContent=me.phone;document.getElementById('logout').classList.remove('hidden');document.getElementById('logout').onclick=async()=>{try{await api('logout',{});location.href='/login';}catch(e){message(e.message);}};if(me.role==='admin')document.getElementById('adminLink').classList.remove('hidden');}const path=location.pathname;if(path==='/login'||path==='/register'){if(me){location.replace('/');return;}authPage(path==='/register');}else if(!me)location.replace('/login');else if(path==='/members'){if(me.role!=='admin'){message('Chỉ admin được quản lý thành viên.');return;}await membersPage();}else await libraryPage();}catch(e){message(e.message);}})();
</script></body></html>'''

WIDGET = '''(()=>{const box=document.createElement('div');box.style.cssText='position:fixed;bottom:14px;right:14px;z-index:9999;background:#172034;padding:10px 16px;border:1px solid #46526b;border-radius:12px;color:white;font:14px system-ui;display:flex;gap:14px;align-items:center';fetch('/member-api/me',{credentials:'same-origin'}).then(r=>r.json()).then(({user})=>{if(!user){location.href='/login';return;}const name=document.createElement('span');name.textContent=user.phone;box.append(name);for(const [href,label] of [['/prompts','Thư viện lời nhắc'],...(user.role==='admin'?[['/members','Quản lý thành viên']]:[])]){const a=document.createElement('a');a.href=href;a.textContent=label;a.style.color='#a7caff';box.append(a);}const button=document.createElement('button');button.textContent='Đăng xuất';button.onclick=async()=>{const r=await fetch('/member-api/logout',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':user.csrf},body:'{}'});if(r.ok)location.href='/login';};box.append(button);document.body.append(box);}).catch(()=>{});})();'''
